PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY,handle TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,bio TEXT NOT NULL DEFAULT '',avatar TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,parent_id TEXT REFERENCES posts(id) ON DELETE RESTRICT,content TEXT NOT NULL,posted_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS posts_account_date ON posts(account_id,posted_at DESC);
CREATE INDEX IF NOT EXISTS posts_parent ON posts(parent_id);
